/* MediaPipe's short-range BlazeFace detector, adapted for the table's existing
 * faceapi.tf runtime. Source and redistribution terms: guest-face-verify-LICENSE.txt.
 * Original half-precision weights; the unused six facial keypoints are omitted.
 */
(() => {
  'use strict';
  const SIZE = 128;
  const CONTEXT = 2.1;
  const BLOCK_CHANNELS = [24, 28, 32, 36, 42, 48, 56, 64, 72, 80, 88, 96, 96, 96, 96, 96];
  const PACKED_WEIGHTS = '';
  let model;
  let runtimeReady;

  function readModel(tf) {
    const binary = atob(PACKED_WEIGHTS);
    let offset = 0;
    function tensor(shape) {
      const count = shape.reduce((total, n) => total*n, 1);
      const values = new Float32Array(count);
      for (let i=0; i<count; i++) {
        const bits = binary.charCodeAt(offset++) | (binary.charCodeAt(offset++) << 8);
        const exponent = (bits >> 10) & 31;
        const mantissa = bits & 1023;
        const value = exponent ? (1024+mantissa) * 2 ** (exponent-25) : mantissa * 2 ** -24;
        values[i] = bits & 32768 ? -value : value;
      }
      return tf.tensor(values,shape);
    }
    function convolution(shape, outputs) {
      return {kernel:tensor(shape), bias:tensor([outputs])};
    }
    const first = convolution([5,5,3,24],24);
    let inputs = 24;
    const blocks = BLOCK_CHANNELS.map((outputs,i) => {
      const depth = convolution([3,3,inputs,1],inputs);
      const point = convolution([1,1,inputs,outputs],outputs);
      const stride = [2,5,11].includes(i) ? 2 : 1;
      inputs = outputs;
      return {depth,point,stride};
    });
    const heads = [[88,2],[96,6]].map(([inputs,anchors]) => ({
      scores:convolution([1,1,inputs,anchors],anchors),
      bounds:convolution([1,1,inputs,anchors*4],anchors*4)
    }));
    if (offset !== binary.length) throw Error('The face verification weights are incomplete.');
    return {first,blocks,heads};
  }

  function predict(tf, rgb, count) {
    if (!model) model = tf.tidy(() => readModel(tf));
    function conv(x, weights, stride=1) {
      return tf.add(tf.conv2d(x,weights.kernel,stride,'same'),weights.bias);
    }
    return tf.tidy(() => {
      const input = tf.tensor4d(rgb,[count,SIZE,SIZE,3]);
      let features = tf.relu(conv(input,model.first,2));
      const heads = [];
      for (const [index,block] of model.blocks.entries()) {
        const last = features;
        features = tf.tidy(() => {
          const depth = tf.add(tf.depthwiseConv2d(last,block.depth.kernel,block.stride,'same'),block.depth.bias);
          const projected = conv(depth,block.point);
          let skip = block.stride===2 ? tf.maxPool(last,2,2,'same') : last;
          const extra = projected.shape[3]-skip.shape[3];
          if (extra) skip = tf.pad(skip,[[0,0],[0,0],[0,0],[0,extra]]);
          return tf.relu(tf.add(projected,skip));
        });
        last.dispose();
        // Two anchors at each of 16 x 16 locations, then six at each of 8 x 8.
        if (index===10 || index===15) {
          const head = model.heads[heads.length];
          heads.push({
            scores:conv(features,head.scores).dataSync(),
            bounds:conv(features,head.bounds).dataSync(),
            cells:features.shape[1], anchors:index===10 ? 2 : 6
          });
        }
      }
      return heads;
    });
  }

  function candidate(heads, item, box) {
    let best = null;
    for (const {scores,bounds,cells,anchors} of heads) {
      const size = cells*cells*anchors, offset = item*size;
      for (let i=0; i<size; i++) {
        const logit = scores[offset+i];
        if (logit<0) continue;  // MediaPipe's normal short-range confidence threshold is 0.5.
        const score = 1/(1+Math.exp(-logit));
        if (best && score<=best.score) continue;
        const cell = Math.floor(i/anchors), k = (offset+i)*4;
        const dx = (cell%cells+.5)/cells + bounds[k]/SIZE - .5;
        const dy = (Math.floor(cell/cells)+.5)/cells + bounds[k+1]/SIZE - .5;
        const width = bounds[k+2]*CONTEXT/SIZE, height = bounds[k+3]*CONTEXT/SIZE;
        // A second face elsewhere in the crop must never validate this box.
        if (Math.hypot(dx,dy)>.18 || width<.55 || width>1.6 || height<.55 || height>1.6) continue;
        const side = CONTEXT*box.w;
        best = {score, x:box.x+side*dx, y:box.y+side*dy, w:box.w*width, h:box.w*height};
      }
    }
    return best;
  }

  // The same model can also propose faces anywhere inside a wide photo tile.
  // These suggestions get checked by the independent Haar detector afterwards.
  function tileFaces(heads,item,tile) {
    const matches=[];
    for (const {scores,bounds,cells,anchors} of heads) {
      const size=cells*cells*anchors, offset=item*size;
      for (let i=0;i<size;i++) {
        if (scores[offset+i]<Math.log(4)) continue; // 80% model confidence
        const cell=Math.floor(i/anchors), k=(offset+i)*4;
        const x=tile.x+tile.side*((cell%cells+.5)/cells+bounds[k]/SIZE-.5);
        const y=tile.y+tile.side*((Math.floor(cell/cells)+.5)/cells+bounds[k+1]/SIZE-.5);
        const w=tile.side*bounds[k+2]/SIZE, h=tile.side*bounds[k+3]/SIZE;
        if (Math.min(w,h)>=18) matches.push({x,y,w,h,score:1/(1+Math.exp(-scores[offset+i]))});
      }
    }
    return matches;
  }

  async function inferTiles(image,tiles,read) {
    const tf=window.faceapi?.tf;
    if (!tf) throw Error('The local face model runtime is missing.');
    await window.loadGuestLandmarks();
    let source=image;
    if (image.data) {
      source=document.createElement('canvas'); source.width=image.width; source.height=image.height;
      source.getContext('2d').putImageData(image,0,0);
    }
    const tile=document.createElement('canvas'); tile.width=tile.height=SIZE;
    const ctx=tile.getContext('2d',{willReadFrequently:true});
    const results=[];
    for (let start=0;start<tiles.length;start+=4) {
      const batch=tiles.slice(start,start+4), rgb=new Float32Array(batch.length*SIZE*SIZE*3);
      let index=0;
      for (const {x,y,side} of batch) {
        ctx.fillStyle='#808080';ctx.fillRect(0,0,SIZE,SIZE);
        ctx.drawImage(source,x-side/2,y-side/2,side,side,0,0,SIZE,SIZE);
        const rgba=ctx.getImageData(0,0,SIZE,SIZE).data;
        for (let p=0;p<rgba.length;p+=4) {
          rgb[index++]=rgba[p]/127.5-1;
          rgb[index++]=rgba[p+1]/127.5-1;
          rgb[index++]=rgba[p+2]/127.5-1;
        }
      }
      const heads=predict(tf,rgb,batch.length);
      batch.forEach((area,i)=>results.push(read(heads,i,area)));
      if (start+batch.length<tiles.length) await tf.nextFrame();
    }
    return results;
  }

  // Boxes and returned detections use center x,y and full width in source pixels.
  async function check(image,boxes) {
    const tiles=[];
    boxes.forEach((b,i)=>{
      if (b && [b.x,b.y,b.w].every(Number.isFinite) && b.w>0)
        tiles.push({...b,side:CONTEXT*b.w,index:i});
    });
    const result=boxes.map(()=>null);
    if (tiles.length) {
      const matches=await inferTiles(image,tiles,candidate);
      tiles.forEach((t,i)=>{result[t.index]=matches[i];});
    }
    return result;
  }

  async function scanPanorama(image) {
    const {width,height}=image, horizontal=width>=height;
    const across=Math.max(width,height), side=Math.max(Math.min(width,height),across/6);
    const count=1+Math.ceil((across-side)/(.65*side));
    const tiles=Array.from({length:count},(_,i)=>{
      const center=side/2+(across-side)*i/Math.max(1,count-1);
      return {x:horizontal?center:width/2,y:horizontal?height/2:center,side};
    });
    const matches=(await inferTiles(image,tiles,tileFaces)).flat().sort((a,b)=>b.score-a.score);
    const unique=[];
    for (const b of matches) {
      if (!unique.some(a=>Math.hypot(a.x-b.x,a.y-b.y)<.4*Math.min(a.w,b.w))) unique.push(b);
    }
    return unique;
  }
  window.GuestFaceVerify={check,scanPanorama};
})();
